// Normalize incoming WhatsApp message
const body = $input.item.json.body || {};

const from = body.from || "unknown";
const message = body.message || "";
const timestamp = body.timestamp || new Date().toISOString();
const profileName = body.profile_name || "Usuario";

// Hash phone number for privacy (don't store full number)
const crypto = require('crypto');
const hashedFrom = crypto.createHash('sha256').update(from).digest('hex').substring(0, 16);

return {
  json: {
    from_hash: hashedFrom,
    message: message,
    message_lower: message.toLowerCase(),
    timestamp: timestamp,
    profile_name: profileName,
    original_length: message.length
  }
};

// Keyword-based categorizer for WhatsApp messages
const message = $input.item.json.message_lower || "";

// Category keywords
const keywords = {
  security: [
    "robo", "asalto", "arma", "disparos", "violencia", "secuestro",
    "amenaza", "delincuente", "ladrón", "asaltante"
  ],
  medical: [
    "herido", "inconsciente", "sangrado", "ambulancia", "infarto",
    "convulsiones", "dolor", "accidente", "lesión", "enfermo"
  ],
  protection_civil: [
    "incendio", "fuga de gas", "derrumbe", "inundación", "explosión",
    "fuego", "humo", "gas", "temblor", "sismo"
  ],
  public_services: [
    "bache", "semáforo", "alumbrado", "árbol caído", "fuga de agua",
    "basura", "alcantarilla", "poste", "cable"
  ],
  social_support: [
    "persona vulnerable", "adulto mayor", "extraviado", "indigencia",
    "abandono", "sin hogar", "perdido"
  ],
  victim_attention: [
    "violencia familiar", "abuso", "agresión", "víctima", "maltrato",
    "violencia doméstica", "golpes"
  ]
};

// P0 keywords (critical signals)
const p0Keywords = [
  "sangre", "sangrado grave", "inconsciente", "arma de fuego",
  "incendio", "explosión", "bebé", "niño", "niña", "secuestro",
  "amenaza de muerte", "no respira"
];

// Detect category
let detectedCategory = "unknown";
let maxMatches = 0;
let detectedKeywords = [];

for (const [category, categoryKeywords] of Object.entries(keywords)) {
  let matches = 0;
  const foundKeywords = [];

  for (const keyword of categoryKeywords) {
    if (message.includes(keyword)) {
      matches++;
      foundKeywords.push(keyword);
    }
  }

  if (matches > maxMatches) {
    maxMatches = matches;
    detectedCategory = category;
    detectedKeywords = foundKeywords;
  }
}

// Detect P0 signals
const p0Signals = [];
for (const p0Keyword of p0Keywords) {
  if (message.includes(p0Keyword)) {
    p0Signals.push(p0Keyword);
  }
}

// Determine risk hint
let riskHint = "low";
if (p0Signals.length > 0) {
  riskHint = "critical";
} else if (detectedCategory === "security" || detectedCategory === "medical" || detectedCategory === "protection_civil") {
  riskHint = "mid";
}

// Extract location hint (simple pattern matching)
const locationPatterns = [
  /en\s+([a-záéíóúñ\s]+)/i,
  /colonia\s+([a-záéíóúñ\s]+)/i,
  /calle\s+([a-záéíóúñ\s]+)/i
];

let locationHint = "";
for (const pattern of locationPatterns) {
  const match = message.match(pattern);
  if (match && match[1]) {
    locationHint = match[1].trim().substring(0, 50);
    break;
  }
}

return {
  json: {
    ...($input.item.json),
    case_category: detectedCategory,
    detected_keywords: detectedKeywords,
    p0_signals: p0Signals,
    risk_hint: riskHint,
    location_hint: locationHint || "Ubicación no especificada",
    classification_confidence: maxMatches > 0 ? "high" : "low"
  }
};

// Build 911 call payload for main workflow
const data = $input.item.json;

// Build transcript (sanitized)
const transcript = `Reporte vía WhatsApp Bot: ${data.message}`;

// Build metadata
const metadata = {
  source: "whatsapp_bot_demo",
  from_hash: data.from_hash,
  profile_name: data.profile_name,
  detected_category: data.case_category,
  detected_keywords: data.detected_keywords,
  p0_signals: data.p0_signals,
  risk_hint: data.risk_hint,
  classification_confidence: data.classification_confidence,
  bot_processed_at: new Date().toISOString()
};

return {
  json: {
    transcript: transcript,
    location_hint: data.location_hint,
    solid_consent: true,
    metadata: metadata
  }
};

// Build bot response for WhatsApp user
const callResult = $input.item.json;
const originalData = $node["Keyword Categorizer"].json;

// Determine response based on category and risk
let responseMessage = "";

if (originalData.p0_signals && originalData.p0_signals.length > 0) {
  responseMessage = `⚠️ EMERGENCIA CRÍTICA DETECTADA\n\n`;
  responseMessage += `Tu reporte ha sido clasificado como PRIORIDAD MÁXIMA.\n\n`;
  responseMessage += `Categoría: ${originalData.case_category}\n`;
  responseMessage += `Señales P0: ${originalData.p0_signals.join(", ")}\n\n`;
  responseMessage += `Un operador humano revisará tu caso de inmediato.\n\n`;
} else if (originalData.risk_hint === "mid" || originalData.risk_hint === "critical") {
  responseMessage = `✅ Reporte recibido\n\n`;
  responseMessage += `Tu reporte ha sido clasificado como: ${originalData.case_category}\n`;
  responseMessage += `Nivel de prioridad: ${originalData.risk_hint === "critical" ? "CRÍTICO" : "MEDIO"}\n\n`;
  responseMessage += `Un operador humano debe revisar el caso.\n\n`;
} else {
  responseMessage = `✅ Reporte recibido\n\n`;
  responseMessage += `Tu reporte ha sido registrado.\n`;
  responseMessage += `Categoría: ${originalData.case_category}\n\n`;
  responseMessage += `Será procesado según prioridad.\n\n`;
}

// Add folio
if (callResult.call_id) {
  responseMessage += `Folio: ${callResult.call_id.substring(0, 8)}\n`;
}

if (callResult.incident_id) {
  responseMessage += `Incidente: ${callResult.incident_id.substring(0, 8)}\n`;
}

responseMessage += `\nGracias por tu reporte. 🚨`;

return {
  json: {
    status: "success",
    bot_reply: responseMessage,
    call_id: callResult.call_id,
    incident_id: callResult.incident_id,
    risk_level: callResult.risk_level,
    branch: callResult.branch,
    case_category: callResult.case_category,
    human_required: callResult.human_required,
    processed_at: callResult.processed_at
  }
};

// Error handler
const error = $input.item.json.error || "Unknown error";

return {
  json: {
    status: "error",
    bot_reply: "❌ Lo sentimos, hubo un error al procesar tu reporte. Por favor intenta nuevamente o llama al 911.",
    error: error,
    timestamp: new Date().toISOString()
  }
};
